    """Un 4xx sul `PUT pax` (ProductError dall'adapter HTTP): i `refId` non sono quelli attesi."""
    from vela.ports.hofj import ProductError
    return isinstance(exc, ProductError)


def _describe(exc: Exception) -> str:
    return ("%s: %s" % (type(exc).__name__, exc))[:500]
